"""Derived scan-sequence constants for the of135i driver.

AUTO-GENERATED by driver/gen_tables.py from
traces/03-singel-3600-IRav.trace.json.gz -- do not edit by hand.
Regenerate with: .venv/bin/python driver/gen_tables.py

Structures the verified 3600 dpi single-frame scan flow (see
driver-design.md 'Scan sequence' and protocol-notes.md) as an
ordered list of PHASES. Each Phase holds its FULL verbatim op
stream (control writes/reads, coalesced status polls, bulk-OUT
and bulk-IN, in captured order with captured dt pacing) for its
trace op-index range -- see device.py's executor, which replays
phases with replay_trace.py semantics (same cw/cr/poll/bo/bi
handling, same dt pacing, plus the hardware-discovered engine-
busy wait after any execute pulse). Injection points (AFE
gain/offset codes, FEEDL, line count, shading upload payload)
are named placeholders patched by device.py at runtime -- see
Phase.injections/patched() and calibrate.py.
"""

from __future__ import annotations

from dataclasses import dataclass, field, replace


@dataclass(frozen=True)
class Op:
    """One verbatim operation from the captured trace, in order.

    kind: 'cw' (control write), 'cr' (control read), 'poll'
        (coalesced repeated control read), 'bo' (bulk OUT), or
        'bi' (bulk IN).
    dt: seconds since the previous op in the capture -- replayed
        as a pacing sleep when above device.py's threshold.
    bm/br/wv/wi: control-transfer setup fields (cw/cr/poll only).
    data: payload bytes (cw control-write data, bo bulk-OUT
        payload); b'' for cr/poll/bi.
    length: expected reply length (cr/poll) or bulk-IN chunk
        length (bi); 0 for cw/bo.
    resp: expected response bytes (cr: the captured reply; poll:
        the final settled reply) -- informational, a live
        mismatch is logged, not enforced.
    dur: captured poll duration in seconds, used to scale the
        replay timeout (poll only).
    """

    kind: str
    dt: float = 0.0
    bm: int = 0
    br: int = 0
    wv: int = 0
    wi: int = 0
    data: bytes = b""
    length: int = 0
    resp: bytes = b""
    dur: float = 0.0


@dataclass
class Phase:
    """One named step of the scan sequence, as its full verbatim
    op stream.

    ops: ordered verbatim ops (see Op) for this phase's trace
        op-index range, captured (frame-1, 3600 dpi) values baked
        in; callers that want computed values patch a copy via
        `patched()`.
    injections: name -> spec for the ops that carry computed
        values instead of their captured ones:
          ("byte", op_index, byte_offset) -- a single/multi-byte
            splice into ops[op_index].data at byte_offset.
          ("bo", (op_index, ...)) -- a full payload, split across
            the named bo ops' *original* chunk lengths, in order
            (the shading-table upload/re-upload).
    split_at: for cal_shading_verify only -- the local op index
        of its re-upload's buffer-write descriptor. Everything
        before it (the re-measurement) can run standalone; the
        shading_table2 injection depends on that measurement, so
        device.py runs ops[:split_at], computes it, then runs
        patched(shading_table2=...)[split_at:].
    """

    name: str
    op_range: tuple[int, int]   # trace op-index range this phase covers (provenance)
    ops: list[Op] = field(default_factory=list)
    injections: dict[str, tuple] = field(default_factory=dict)
    split_at: int | None = None

    def patched(self, **values: bytes) -> list[Op]:
        """Return a copy of ops with named injection points
        overwritten by the given values (see `injections` above).

        Unknown names in `values` are ignored (a phase may not
        carry every injection point another phase does).
        """
        out = list(self.ops)
        for name, val in values.items():
            spec = self.injections.get(name)
            if spec is None:
                continue
            if spec[0] == "byte":
                _, idx, off = spec
                data = bytearray(out[idx].data)
                data[off:off + len(val)] = val
                out[idx] = replace(out[idx], data=bytes(data))
            elif spec[0] == "bo":
                _, idxs = spec
                total = sum(len(out[idx].data) for idx in idxs)
                if len(val) > total:
                    raise ValueError(
                        f"injection {name!r}: got {len(val)} B, "
                        f"expected at most {total} B"
                    )
                # The captured chunk lengths include trailing USB-
                # packet padding beyond the real payload (e.g. shading
                # uploads: 46080 B wire vs. 45856 B of real data) --
                # zero-pad a shorter computed value out to the same shape.
                padded = bytes(val) + bytes(total - len(val))
                pos = 0
                for idx in idxs:
                    n = len(out[idx].data)
                    out[idx] = replace(out[idx], data=padded[pos:pos + n])
                    pos += n
        return out


