# step-time curves). SLOPE_TABLE_POSITION is written to 0x1000c000 and
# 0x10010000 in the 'position' phase; SLOPE_TABLE_SCAN is written to
# 0x10000000, 0x10004000 and 0x10008000 (identical payload each time)
# in the 'scan' phase.
SLOPE_TABLE_POSITION = bytes.fromhex(
    ""
)

